<?php $page='settings';require __DIR__.'/_head.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$keys=['site_name','site_tagline','site_email','site_phone','github_url','linkedin_url','about_text','meta_title','meta_description','smtp_host','smtp_port','smtp_user','smtp_pass','smtp_secure'];$st=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($keys as $k)$st->execute([$k,trim($_POST[$k]??'')]);$cv=upload_file('cv','uploads/cv',['application/pdf'=>'pdf','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx']);if($cv)$st->execute(['cv_url',$cv]);$msg='Settings saved.';}catch(Throwable $e){$msg=$e->getMessage();}}?><div class="topbar"><h1>Site Settings</h1></div><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><form class="form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="row"><label>Site name<input name="site_name" value="<?=e(setting('site_name'))?>"></label><label>Tagline<input name="site_tagline" value="<?=e(setting('site_tagline'))?>"></label></div><div class="row"><label>Email<input type="email" name="site_email" value="<?=e(setting('site_email'))?>"></label><label>Phone<input name="site_phone" value="<?=e(setting('site_phone'))?>"></label></div><div class="row"><label>GitHub<input name="github_url" value="<?=e(setting('github_url'))?>"></label><label>LinkedIn<input name="linkedin_url" value="<?=e(setting('linkedin_url'))?>"></label></div><label>About<textarea name="about_text"><?=e(setting('about_text'))?></textarea></label><div class="row"><label>SEO title<input name="meta_title" value="<?=e(setting('meta_title'))?>"></label><label>SEO description<input name="meta_description" value="<?=e(setting('meta_description'))?>"></label></div><h2>SMTP (optional)</h2><p class="muted">These fields are stored for future SMTP integration. The current contact endpoint uses PHP mail().</p><div class="row"><label>SMTP host<input name="smtp_host" value="<?=e(setting('smtp_host'))?>" placeholder="smtp.hostinger.com"></label><label>Port<input name="smtp_port" value="<?=e(setting('smtp_port','587'))?>"></label></div><div class="row"><label>SMTP username<input name="smtp_user" value="<?=e(setting('smtp_user'))?>"></label><label>SMTP password<input type="password" name="smtp_pass" value="<?=e(setting('smtp_pass'))?>"></label></div><label>CV upload<input type="file" name="cv" accept=".pdf,.doc,.docx"></label><button class="btn primary">Save settings</button></form></div><?php require __DIR__.'/_foot.php';
